-- Attendance/timetable module. Every business table carries college_id for tenant isolation.
CREATE TABLE IF NOT EXISTS academic_years (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),name VARCHAR(50) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,active BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,name));
CREATE TABLE IF NOT EXISTS academic_terms (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),academic_year_id BIGINT NOT NULL REFERENCES academic_years(id),name VARCHAR(80) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,academic_year_id,name));
CREATE TABLE IF NOT EXISTS academic_programs (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),code VARCHAR(30) NOT NULL,name VARCHAR(120) NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,code));
CREATE TABLE IF NOT EXISTS academic_semesters (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),program_id BIGINT NOT NULL REFERENCES academic_programs(id),number INTEGER NOT NULL,name VARCHAR(80) NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,program_id,number));
CREATE TABLE IF NOT EXISTS academic_classes (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),program_id BIGINT NOT NULL REFERENCES academic_programs(id),semester_id BIGINT REFERENCES academic_semesters(id),name VARCHAR(100) NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,program_id,semester_id,name));
CREATE TABLE IF NOT EXISTS academic_sections (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),class_id BIGINT NOT NULL REFERENCES academic_classes(id),name VARCHAR(40) NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,class_id,name));
CREATE TABLE IF NOT EXISTS academic_subjects (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),program_id BIGINT NOT NULL REFERENCES academic_programs(id),semester_id BIGINT REFERENCES academic_semesters(id),code VARCHAR(30) NOT NULL,name VARCHAR(140) NOT NULL,type VARCHAR(20) NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,code));
CREATE TABLE IF NOT EXISTS academic_rooms (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),code VARCHAR(30) NOT NULL,name VARCHAR(100) NOT NULL,capacity INTEGER NOT NULL,type VARCHAR(20) NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,code));
CREATE TABLE IF NOT EXISTS academic_periods (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),period_number INTEGER NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,type VARCHAR(20) NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,period_number),CHECK(end_time>start_time));
CREATE TABLE IF NOT EXISTS academic_working_days (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),day_of_week VARCHAR(12) NOT NULL,working BOOLEAN NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,day_of_week));
CREATE TABLE IF NOT EXISTS academic_holidays (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),holiday_date DATE NOT NULL,name VARCHAR(160) NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,holiday_date));
CREATE TABLE IF NOT EXISTS teacher_subject_assignments (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),teacher_id BIGINT NOT NULL REFERENCES users(id),subject_id BIGINT NOT NULL REFERENCES academic_subjects(id),class_id BIGINT NOT NULL REFERENCES academic_classes(id),section_id BIGINT NOT NULL REFERENCES academic_sections(id),created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,teacher_id,subject_id,class_id,section_id));
CREATE TABLE IF NOT EXISTS class_teacher_assignments (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),academic_year_id BIGINT NOT NULL REFERENCES academic_years(id),teacher_id BIGINT NOT NULL REFERENCES users(id),class_id BIGINT NOT NULL REFERENCES academic_classes(id),section_id BIGINT NOT NULL REFERENCES academic_sections(id),created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,academic_year_id,class_id,section_id));
CREATE TABLE IF NOT EXISTS student_enrollments (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),academic_year_id BIGINT NOT NULL REFERENCES academic_years(id),student_id BIGINT NOT NULL REFERENCES student_profiles(id),class_id BIGINT NOT NULL REFERENCES academic_classes(id),section_id BIGINT NOT NULL REFERENCES academic_sections(id),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,academic_year_id,student_id));
CREATE TABLE IF NOT EXISTS timetables (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),academic_year_id BIGINT NOT NULL REFERENCES academic_years(id),academic_term_id BIGINT NOT NULL REFERENCES academic_terms(id),class_id BIGINT NOT NULL REFERENCES academic_classes(id),section_id BIGINT NOT NULL REFERENCES academic_sections(id),week_start DATE NOT NULL,status VARCHAR(20) NOT NULL,created_by BIGINT NOT NULL REFERENCES users(id),published_by BIGINT REFERENCES users(id),published_at TIMESTAMP,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,academic_term_id,class_id,section_id,week_start));
CREATE TABLE IF NOT EXISTS timetable_entries (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),timetable_id BIGINT NOT NULL REFERENCES timetables(id) ON DELETE CASCADE,day_of_week VARCHAR(12) NOT NULL,period_id BIGINT NOT NULL REFERENCES academic_periods(id),subject_id BIGINT REFERENCES academic_subjects(id),teacher_id BIGINT REFERENCES users(id),room_id BIGINT REFERENCES academic_rooms(id),type VARCHAR(20) NOT NULL,created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,timetable_id,day_of_week,period_id));
CREATE TABLE IF NOT EXISTS attendance_sessions (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),timetable_entry_id BIGINT REFERENCES timetable_entries(id),session_date DATE NOT NULL,session_type VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,assigned_teacher_id BIGINT NOT NULL REFERENCES users(id),lock_at TIMESTAMP NOT NULL,submitted_at TIMESTAMP,submitted_by BIGINT REFERENCES users(id),created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,timetable_entry_id,session_date));
CREATE TABLE IF NOT EXISTS student_attendance (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),session_id BIGINT NOT NULL REFERENCES attendance_sessions(id),student_id BIGINT NOT NULL REFERENCES student_profiles(id),status VARCHAR(20) NOT NULL,remarks VARCHAR(500),marked_by BIGINT NOT NULL REFERENCES users(id),marked_at TIMESTAMP NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(college_id,session_id,student_id));
CREATE TABLE IF NOT EXISTS attendance_corrections (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),attendance_id BIGINT NOT NULL REFERENCES student_attendance(id),old_status VARCHAR(20) NOT NULL,new_status VARCHAR(20) NOT NULL,reason VARCHAR(500) NOT NULL,corrected_by BIGINT NOT NULL REFERENCES users(id),corrected_at TIMESTAMP NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS erp_audit_logs (id BIGSERIAL PRIMARY KEY,college_id BIGINT NOT NULL REFERENCES colleges(id),action VARCHAR(80) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT,actor_id BIGINT NOT NULL REFERENCES users(id),details TEXT,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL);
CREATE INDEX IF NOT EXISTS idx_timetable_teacher_time ON timetable_entries(college_id,teacher_id,day_of_week);
CREATE INDEX IF NOT EXISTS idx_timetable_room_time ON timetable_entries(college_id,room_id,day_of_week);
CREATE INDEX IF NOT EXISTS idx_sessions_tenant_date ON attendance_sessions(college_id,session_date);
CREATE INDEX IF NOT EXISTS idx_attendance_student ON student_attendance(college_id,student_id);
CREATE INDEX IF NOT EXISTS idx_audit_tenant_time ON erp_audit_logs(college_id,created_at);
